import {
  tableColorStripHeight,
  tableFieldHeight,
  tableHeaderHeight,
} from "../data/constants";

export function arrangeTables(diagram) {
  let maxHeight = -1;
  const tableWidth = 200;
  const gapX = 54;
  const gapY = 40;
  diagram.tables.forEach((table, i) => {
    if (i < diagram.tables.length / 2) {
      table.x = i * tableWidth + (i + 1) * gapX;
      table.y = gapY;
      const height =
        table.fields.length * tableFieldHeight +
        tableHeaderHeight +
        tableColorStripHeight;
      maxHeight = Math.max(height, maxHeight);
    } else {
      const index = diagram.tables.length - i - 1;
      table.x = index * tableWidth + (index + 1) * gapX;
      table.y = maxHeight + 2 * gapY;
    }
  });
}

src/utils/autoArrange.js:
import { graphlib, layout } from "@dagrejs/dagre";
import { tableWidth as defaultTableWidth } from "../data/constants";
import {
  getRelatedFieldKeysByTable,
  getTableHeight,
  getTableWidth,
} from "./utils";

const nodeSep = 60;
const rankSep = 110;
const isolatedGap = 60;
const targetRatio = 16 / 9;
const minRatio = 1 / 3;
const maxRatio = 4;

export function autoArrange(
  tables,
  relationships,
  settings,
  { direction = "LR" } = {},
) {
  const movable = tables.filter((table) => !table.locked);
  const movableIds = new Set(movable.map((table) => table.id));

  const connectedIds = new Set();
  for (const r of relationships) {
    if (
      r.startTableId !== r.endTableId &&
      movableIds.has(r.startTableId) &&
      movableIds.has(r.endTableId)
    ) {
      connectedIds.add(r.startTableId);
      connectedIds.add(r.endTableId);
    }
  }

  const relatedFieldKeysByTable = getRelatedFieldKeysByTable(relationships);
  const sizeOf = (table) => ({
    width: getTableWidth(table),
    height: getTableHeight(
      table,
      settings.showComments,
      relatedFieldKeysByTable.get(table.id),
    ),
  });

  const connected = movable.filter((table) => connectedIds.has(table.id));
  const isolated = movable.filter((table) => !connectedIds.has(table.id));

  const graph = new graphlib.Graph();
  graph.setGraph({ rankdir: direction, nodesep: nodeSep, ranksep: rankSep });
  graph.setDefaultEdgeLabel(() => ({}));

  for (const table of connected) {
    graph.setNode(String(table.id), sizeOf(table));
  }
  for (const r of relationships) {
    if (
      r.startTableId !== r.endTableId &&
      connectedIds.has(r.startTableId) &&
      connectedIds.has(r.endTableId)
    ) {
      graph.setEdge(String(r.startTableId), String(r.endTableId));
    }
  }

  layout(graph);

  const placed = connected.map((table) => {
    const node = graph.node(String(table.id));
    return {
      id: table.id,
      x: node.x - node.width / 2,
      y: node.y - node.height / 2,
      width: node.width,
      height: node.height,
      rank: Math.round(node.x),
    };
  });

  const extent = () => ({
    width: Math.max(0, ...placed.map((p) => p.x + p.width)),
    height: Math.max(0, ...placed.map((p) => p.y + p.height)),
  });
  let { width: maxX, height: maxY } = extent();

  const ratio = maxX / maxY;
  if (
    direction === "LR" &&
    placed.length > 1 &&
    (ratio < minRatio || ratio > maxRatio)
  ) {
    const ranks = new Map();
    for (const p of [...placed].sort((a, b) => a.y - b.y)) {
      if (!ranks.has(p.rank)) ranks.set(p.rank, []);
      ranks.get(p.rank).push(p);
    }

    const rankOrder = [...ranks.keys()].sort((a, b) => b - a);
    const buildColumns = (heightLimit) => {
      const columns = [];
      for (const rank of rankOrder) {
        const nodes = ranks.get(rank);
        const rankHeight = nodes.reduce(
          (sum, p) => sum + p.height + nodeSep,
          0,
        );
        const columnHeight =
          rankHeight / Math.max(1, Math.ceil(rankHeight / heightLimit));
        let column = null;
        for (const p of nodes) {
          if (!column || column.height + p.height > columnHeight) {
            column = { nodes: [], width: 0, height: 0 };
            columns.push(column);
          }
          column.nodes.push({ p, offset: column.height });
          column.height += p.height + nodeSep;
          column.width = Math.max(column.width, p.width);
        }
      }
      return columns;
    };

    const placeColumns = (columns, bandWidth) => {
      const slots = [];
      let x = 0;
      let y = 0;
      let width = 0;
      let bandHeight = 0;
      for (const column of columns) {
        let gap = x === 0 ? 0 : rankSep;
        if (x > 0 && x + gap + column.width > bandWidth) {
          y += bandHeight + rankSep;
          x = 0;
          gap = 0;
          bandHeight = 0;
        }
        slots.push({ column, x: x + gap, y });
        x += gap + column.width;
        width = Math.max(width, x);
        bandHeight = Math.max(bandHeight, column.height - nodeSep);
      }
      const height = y + bandHeight;
      return {
        slots,
        score: Math.abs(Math.log(width / height / targetRatio)),
      };
    };

    const tallest = Math.max(...placed.map((p) => p.height + nodeSep));
    const longest = Math.max(
      ...[...ranks.values()].map((nodes) =>
        nodes.reduce((sum, p) => sum + p.height + nodeSep, 0),
      ),
    );
    let best = null;
    for (let step = 0; step <= 12; step++) {
      const columns = buildColumns(
        tallest * Math.pow(longest / tallest, step / 12),
      );
      const totalWidth =
        columns.reduce((sum, column) => sum + column.width + rankSep, 0) -
        rankSep;
      for (let bands = 1; bands <= columns.length; bands++) {
        const candidate = placeColumns(columns, totalWidth / bands + 1);
        if (!best || candidate.score < best.score) best = candidate;
      }
    }
    for (const { column, x, y } of best.slots) {
      for (const { p, offset } of column.nodes) {
        p.x = x;
        p.y = y + offset;
      }
    }

    ({ width: maxX, height: maxY } = extent());
  }

  const positions = placed.map(({ id, x, y }) => ({ id, x, y }));

  if (isolated.length > 0) {
    const isolatedArea = isolated.reduce((sum, table) => {
      const { width, height } = sizeOf(table);
      return sum + (width + isolatedGap) * (height + isolatedGap);
    }, 0);
    const rowWidth = Math.max(
      maxX,
      Math.sqrt(isolatedArea * targetRatio),
      4 * defaultTableWidth + 3 * isolatedGap,
    );
    let x = 0;
    let y = connected.length > 0 ? maxY + rankSep : 0;
    let rowHeight = 0;
    for (const table of isolated) {
      const { width, height } = sizeOf(table);
      if (x > 0 && x + width > rowWidth) {
        x = 0;
        y += rowHeight + isolatedGap;
        rowHeight = 0;
      }
      positions.push({ id: table.id, x, y });
      x += width + isolatedGap;
      rowHeight = Math.max(rowHeight, height);
    }
  }

  return positions;
}

src/utils/autoRelationships.js:
import { nanoid } from "nanoid";
import { Cardinality, Constraint } from "../data/constants";
import { getRelationshipFields } from "./utils";

function singularize(name) {
  if (!name || typeof name !== "string") return "";
  const lower = name.trim().toLowerCase();
  if (lower.endsWith("ies")) return lower.slice(0, -3) + "y";
  if (lower.endsWith("es") && !lower.endsWith("sses")) return lower.slice(0, -2);
  if (lower.endsWith("s") && !lower.endsWith("ss")) return lower.slice(0, -1);
  return lower;
}

export function findAutoFKRelationships(tables = [], existingRelationships = []) {
  const newRelationships = [];
  const currentRelationships = [...existingRelationships];

  const isFieldAlreadyLinked = (childTableId, fieldId) => {
    return currentRelationships.some((r) => {
      const pairs = getRelationshipFields(r);
      if (r.startTableId === childTableId) {
        return pairs.some((p) => p.startFieldId === fieldId);
      }
      return false;
    });
  };

  const isPairAlreadyLinked = (childTableId, fkFieldId, parentTableId, pkFieldId) => {
    return currentRelationships.some((r) => {
      const pairs = getRelationshipFields(r);
      const forward =
        r.startTableId === childTableId &&
        r.endTableId === parentTableId &&
        pairs.some((p) => p.startFieldId === fkFieldId && p.endFieldId === pkFieldId);
      const backward =
        r.startTableId === parentTableId &&
        r.endTableId === childTableId &&
        pairs.some((p) => p.startFieldId === pkFieldId && p.endFieldId === fkFieldId);
      return forward || backward;
    });
  };

  tables.forEach((parentTable) => {
    const pkFields = (parentTable.fields || []).filter((f) => f.primary);
    if (pkFields.length === 0) return;

    const pTableName = parentTable.name.trim().toLowerCase();
    const pSingularName = singularize(pTableName);

    pkFields.forEach((pkField) => {
      const pkFieldName = pkField.name.trim().toLowerCase();

      // Candidate matching names for the foreign key column in child tables
      const candidateNames = new Set([
        `${pTableName}_${pkFieldName}`,//users_id
        `${pSingularName}_${pkFieldName}`,//user_id
        `${pTableName}${pkFieldName}`,//usersid
        `${pSingularName}${pkFieldName}`,//userid
      ]);

      if (pkFieldName !== "id") {
        candidateNames.add(pkFieldName);
      }

      tables.forEach((childTable) => {
        if (childTable.id === parentTable.id) return;

        (childTable.fields || []).forEach((fkField) => {
          const fkFieldName = fkField.name.trim().toLowerCase();

          if (!candidateNames.has(fkFieldName)) return;

          if (
            isFieldAlreadyLinked(childTable.id, fkField.id) ||
            isPairAlreadyLinked(childTable.id, fkField.id, parentTable.id, pkField.id)
          ) {
            return;
          }

          const rel = {
            id: nanoid(),
            name: `fk_${childTable.name}_${fkField.name}_${parentTable.name}`,
            startTableId: childTable.id,
            startFieldId: fkField.id,
            endTableId: parentTable.id,
            endFieldId: pkField.id,
            cardinality: fkField.unique
              ? Cardinality.ONE_TO_ONE
              : Cardinality.MANY_TO_ONE,
            updateConstraint: Constraint.NONE,
            deleteConstraint: Constraint.NONE,
          };

          newRelationships.push(rel);
          currentRelationships.push(rel);
        });
      });
    });
  });

  return newRelationships;
}

