export const STORAGE_KEY = "versions_cache";

export function loadCache() {
  try {
    const saved = localStorage.getItem(STORAGE_KEY);
    return saved ? JSON.parse(saved) : {};
  } catch {
    return {};
  }
}

export function saveCache(cache) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(cache));
}

export function deleteFromCache(key) {
  const cache = loadCache();
  if (cache[key]) {
    delete cache[key];
    saveCache(cache);
  }
}

src/utils/calcPath.js:
import { tableFieldHeight, tableHeaderHeight } from "../data/constants";
import { getCommentHeight, getFieldOffsetY, getTableWidth } from "./utils";

/**
 * Generates an SVG path string to visually represent a relationship between two fields.
 *
 * @param {{
 *   startTable: { x: number, y: number, width?: number },
 *   endTable: { x: number, y: number, width?: number },
 *   startFieldIndex: number,
 *   endFieldIndex: number
 * }} r - Relationship data.
 * @param {number} zoom - Zoom level (used to scale vertical spacing).
 * @returns {string} SVG path "d" attribute string.
 */
export function calcPath(r, zoom = 1, showComments = true) {
  if (!r) {
    return "";
  }

  const startTableWidth = getTableWidth(r.startTable);
  const endTableWidth = getTableWidth(r.endTable);
  const startWidth = startTableWidth * zoom;
  const endWidth = endTableWidth * zoom;
  let x1 = r.startTable.x;
  let y1 =
    r.startTable.y +
    getFieldOffsetY(
      r.startTable.fields ?? [],
      r.startFieldIndex,
      startTableWidth,
      showComments,
    ) +
    tableHeaderHeight +
    getCommentHeight(r.startTable.comment, startTableWidth, showComments) +
    tableFieldHeight / 2;
  let x2 = r.endTable.x;
  let y2 =
    r.endTable.y +
    getFieldOffsetY(
      r.endTable.fields ?? [],
      r.endFieldIndex,
      endTableWidth,
      showComments,
    ) +
    getCommentHeight(r.endTable.comment, endTableWidth, showComments) +
    tableHeaderHeight +
    tableFieldHeight / 2;

  let radius = 10 * zoom;
  const midX = (x2 + x1 + startWidth) / 2;
  const endX = x2 + endWidth < x1 ? x2 + endWidth : x2;

  if (Math.abs(y1 - y2) <= 36 * zoom) {
    radius = Math.abs(y2 - y1) / 3;
    if (radius <= 2) {
      if (x1 + startWidth <= x2)
        return `M ${x1 + startWidth} ${y1} L ${x2} ${y2 + 0.1}`;
      else if (x2 + endWidth < x1)
        return `M ${x1} ${y1} L ${x2 + endWidth} ${y2 + 0.1}`;
    }
  }

  if (y1 <= y2) {
    if (x1 + startWidth <= x2) {
      return `M ${x1 + startWidth} ${y1} L ${
        midX - radius
      } ${y1} A ${radius} ${radius} 0 0 1 ${midX} ${y1 + radius} L ${midX} ${
        y2 - radius
      } A ${radius} ${radius} 0 0 0 ${midX + radius} ${y2} L ${endX} ${y2}`;
    } else if (x2 <= x1 + startWidth && x1 <= x2) {
      return `M ${x1 + startWidth} ${y1} L ${
        x2 + endWidth
      } ${y1} A ${radius} ${radius} 0 0 1 ${x2 + endWidth + radius} ${
        y1 + radius
      } L ${x2 + endWidth + radius} ${y2 - radius} A ${radius} ${radius} 0 0 1 ${
        x2 + endWidth
      } ${y2} L ${x2 + endWidth} ${y2}`;
    } else if (x2 + endWidth >= x1 && x2 + endWidth <= x1 + startWidth) {
      return `M ${x1} ${y1} L ${
        x2 - radius
      } ${y1} A ${radius} ${radius} 0 0 0 ${x2 - radius - radius} ${
        y1 + radius
      } L ${x2 - radius - radius} ${y2 - radius} A ${radius} ${radius} 0 0 0 ${
        x2 - radius
      } ${y2} L ${x2} ${y2}`;
    } else {
      return `M ${x1} ${y1} L ${
        midX + radius
      } ${y1} A ${radius} ${radius} 0 0 0 ${midX} ${y1 + radius} L ${midX} ${
        y2 - radius
      } A ${radius} ${radius} 0 0 1 ${midX - radius} ${y2} L ${endX} ${y2}`;
    }
  } else {
    if (x1 + startWidth <= x2) {
      return `M ${x1 + startWidth} ${y1} L ${
        midX - radius
      } ${y1} A ${radius} ${radius} 0 0 0 ${midX} ${y1 - radius} L ${midX} ${
        y2 + radius
      } A ${radius} ${radius} 0 0 1 ${midX + radius} ${y2} L ${endX} ${y2}`;
    } else if (x1 + startWidth >= x2 && x1 + startWidth <= x2 + endWidth) {
      return `M ${x1} ${y1} L ${
        x1 - radius - radius
      } ${y1} A ${radius} ${radius} 0 0 1 ${x1 - radius - radius - radius} ${
        y1 - radius
      } L ${x1 - radius - radius - radius} ${
        y2 + radius
      } A ${radius} ${radius} 0 0 1 ${
        x1 - radius - radius
      } ${y2} L ${endX} ${y2}`;
    } else if (x1 >= x2 && x1 <= x2 + endWidth) {
      return `M ${x1 + startWidth} ${y1} L ${
        x1 + startWidth + radius
      } ${y1} A ${radius} ${radius} 0 0 0 ${x1 + startWidth + radius + radius} ${
        y1 - radius
      } L ${x1 + startWidth + radius + radius} ${
        y2 + radius
      } A ${radius} ${radius} 0 0 0 ${x1 + startWidth + radius} ${y2} L ${
        x2 + endWidth
      } ${y2}`;
    } else {
      return `M ${x1} ${y1} L ${
        midX + radius
      } ${y1} A ${radius} ${radius} 0 0 1 ${midX} ${y1 - radius} L ${midX} ${
        y2 + radius
      } A ${radius} ${radius} 0 0 0 ${midX - radius} ${y2} L ${endX} ${y2}`;
    }
  }
}

/**
 * Builds a "fork" path for a composite (multi-column) foreign key: a short
 * stub from every column on each table converges to a vertical collector,
 * the two collectors are joined by a single orthogonal trunk, and the trunk
 * forks back out to the columns on the other table.
 *
 * @param {{
 *   startTable: { x: number, y: number, width?: number, comment?: string, fields?: any[] },
 *   endTable: { x: number, y: number, width?: number, comment?: string, fields?: any[] },
 *   startFieldIndices: number[],
 *   endFieldIndices: number[],
 * }} r
 * @returns {{
 *   path: string,
 *   labelPoint: { x: number, y: number },
 *   startCardinality: { x: number, y: number },
 *   endCardinality: { x: number, y: number },
 * } | null}
 */
export function calcCompositePath(r, zoom = 1, showComments = true) {
  if (!r || !r.startFieldIndices?.length || !r.endFieldIndices?.length) {
    return null;
  }

  const startTableWidth = getTableWidth(r.startTable);
  const endTableWidth = getTableWidth(r.endTable);
  const startWidth = startTableWidth * zoom;
  const endWidth = endTableWidth * zoom;
  const anchorY = (table, index, tableWidth) =>
    table.y +
    tableHeaderHeight +
    getCommentHeight(table.comment, tableWidth, showComments) +
    getFieldOffsetY(table.fields ?? [], index, tableWidth, showComments) +
    tableFieldHeight / 2;

  const startYs = r.startFieldIndices.map((i) =>
    anchorY(r.startTable, i, startTableWidth),
  );
  const endYs = r.endFieldIndices.map((i) =>
    anchorY(r.endTable, i, endTableWidth),
  );

  // Connect each table on the edge facing the other table.
  const startCenter = r.startTable.x + startWidth / 2;
  const endCenter = r.endTable.x + endWidth / 2;
  const startIsLeft = startCenter <= endCenter;
  const startX = startIsLeft ? r.startTable.x + startWidth : r.startTable.x;
  const endX = startIsLeft ? r.endTable.x : r.endTable.x + endWidth;
  const dir = startIsLeft ? 1 : -1;
  const fork = 24 * zoom;
  const mergeStartX = startX + dir * fork;
  const mergeEndX = endX - dir * fork;

  const minS = Math.min(...startYs);
  const maxS = Math.max(...startYs);
  const minE = Math.min(...endYs);
  const maxE = Math.max(...endYs);
  const trunkStartY = (minS + maxS) / 2;
  const trunkEndY = (minE + maxE) / 2;
  const midX = (mergeStartX + mergeEndX) / 2;

  const radius = 10 * zoom;

  // A column branch: horizontal stub from the table edge to the collector x,
  // a rounded corner, then a vertical run down to the trunk level. Branches
  // overlap on the collector x, reading as a single fork that converges into
  // the trunk.
  const branch = (fromX, fromY, cornerX, toY) => {
    if (Math.abs(fromY - toY) < 0.5) {
      return `M ${fromX} ${fromY} L ${cornerX} ${toY}`;
    }
    const dx = Math.sign(cornerX - fromX);
    const dy = Math.sign(toY - fromY);
    const r = Math.min(
      radius,
      Math.abs(toY - fromY),
      Math.abs(cornerX - fromX),
    );
    return `M ${fromX} ${fromY} L ${cornerX - dx * r} ${fromY} Q ${cornerX} ${fromY} ${cornerX} ${fromY + dy * r} L ${cornerX} ${toY}`;
  };

  // The trunk: a rounded orthogonal connector between the two collectors.
  const trunk = (sx, sy, ex, ey) => {
    if (Math.abs(sy - ey) < 0.5) {
      return `M ${sx} ${sy} L ${ex} ${ey}`;
    }
    const mx = (sx + ex) / 2;
    const dxs = Math.sign(mx - sx);
    const dxe = Math.sign(ex - mx);
    const dy = Math.sign(ey - sy);
    const r = Math.min(
      radius,
      Math.abs(ey - sy) / 2,
      Math.abs(mx - sx) || radius,
    );
    return `M ${sx} ${sy} L ${mx - dxs * r} ${sy} Q ${mx} ${sy} ${mx} ${sy + dy * r} L ${mx} ${ey - dy * r} Q ${mx} ${ey} ${mx + dxe * r} ${ey} L ${ex} ${ey}`;
  };

  const segs = [];
  // Each start column forks into the trunk.
  startYs.forEach((y) =>
    segs.push(branch(startX, y, mergeStartX, trunkStartY)),
  );
  // Single trunk between the two collectors.
  segs.push(trunk(mergeStartX, trunkStartY, mergeEndX, trunkEndY));
  // Each end column forks out of the trunk.
  endYs.forEach((y) => segs.push(branch(endX, y, mergeEndX, trunkEndY)));

  return {
    path: segs.join(" "),
    labelPoint: { x: midX, y: (trunkStartY + trunkEndY) / 2 },
    startCardinality: { x: mergeStartX, y: trunkStartY },
    endCardinality: { x: mergeEndX, y: trunkEndY },
  };
}

src/utils/customTypes.js:
import { Validator } from "jsonschema";
import { DB } from "../data/constants";
import { customTypeEntrySchema } from "../data/schemas";
import { dbToTypes } from "../data/datatypes";

const STORAGE_KEY = "custom_types";
const validator = new Validator();
const validDatabases = new Set(Object.values(DB));

function isValidEntry(entry) {
  return validator.validate(entry, customTypeEntrySchema).valid;
}

function migrateIfNeeded(parsed) {
  if (Array.isArray(parsed)) {
    const result = {};
    for (const item of parsed) {
      if (!item.type || !item.database) continue;
      const db = item.database;
      const name = item.type.toUpperCase();
      if (!validDatabases.has(db)) continue;
      if (!result[db]) result[db] = {};
      result[db][name] = { type: name, color: item.color || "#ccc" };
    }
    return result;
  }
  return parsed;
}

export function getCustomTypes() {
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return {};
    const parsed = migrateIfNeeded(JSON.parse(raw));
    if (typeof parsed !== "object" || parsed === null) return {};
    const result = {};
    for (const [db, types] of Object.entries(parsed)) {
      if (!validDatabases.has(db)) continue;
      if (typeof types !== "object" || types === null) continue;
      for (const [name, entry] of Object.entries(types)) {
        if (!isValidEntry(entry)) continue;
        if (!result[db]) result[db] = {};
        result[db][name] = { type: entry.type, color: entry.color };
      }
    }
    return result;
  } catch {
    return {};
  }
}

export function getCustomTypesForDb(database) {
  const all = getCustomTypes();
  const dbTypes = all[database];
  if (!dbTypes) return {};
  const result = {};
  for (const [name, entry] of Object.entries(dbTypes)) {
    result[name] = {
      type: entry.type,
      color: entry.color,
      checkDefault: () => true,
      hasCheck: false,
      isSized: false,
      hasPrecision: false,
      canIncrement: false,
      noDefault: false,
      isCustom: true,
    };
  }
  return result;
}

export function saveCustomTypes(types) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(types));
}

const BLOB_FALLBACK = {
  type: "BLOB",
  color: "",
  checkDefault: () => true,
  hasCheck: false,
  isSized: false,
  hasPrecision: false,
  canIncrement: false,
  noDefault: true,
  isCustom: false,
};

export function resolveType(database, typeName) {
  const builtIn = dbToTypes[database][typeName];
  if (builtIn) return builtIn;

  const customDb = getCustomTypesForDb(database);
  if (customDb[typeName]) return customDb[typeName];

  return dbToTypes[database]["BLOB"] || BLOB_FALLBACK;
}

export function mergeCustomTypes(incoming) {
  if (typeof incoming !== "object" || incoming === null) return;
  const existing = getCustomTypes();
  for (const [db, types] of Object.entries(incoming)) {
    if (!validDatabases.has(db)) continue;
    if (typeof types !== "object" || types === null) continue;
    if (!existing[db]) existing[db] = {};
    for (const [name, entry] of Object.entries(types)) {
      if (!isValidEntry(entry)) continue;
      if (!existing[db][name]) {
        existing[db][name] = { type: entry.type, color: entry.color };
      }
    }
  }
  saveCustomTypes(existing);
}

src/utils/dbml/applyPlan.js:
export function applyDiagramPlan(plan, ctx) {
  for (const op of plan) {
    switch (op.target) {
      case "enums":
        ctx.setEnums(op.enums);
        break;
      case "table":
        if (op.action === "create") ctx.addTable({ table: op.table }, false);
        else if (op.action === "delete") ctx.deleteTable(op.id, false);
        else ctx.updateTable(op.id, op.values);
        break;
      case "field":
        ctx.updateField(op.tableId, op.fieldId, op.values);
        break;
      case "relationship":
        if (op.action === "create") {
          ctx.addRelationship({ relationship: op.relationship }, false);
        } else if (op.action === "delete") {
          ctx.deleteRelationship(op.id, false);
        } else {
          ctx.updateRelationship(op.id, op.values);
        }
        break;
      default:
        break;
    }
  }
}

src/utils/dbml/diff.js:
const TABLE_KEYS = ["name", "comment", "color", "indices", "uniqueConstraints"];

const FIELD_KEYS = [
  "name",
  "type",
  "size",
  "default",
  "primary",
  "unique",
  "notNull",
  "increment",
  "comment",
  "values",
];

const RELATIONSHIP_KEYS = [
  "name",
  "startTableId",
  "endTableId",
  "startFieldId",
  "endFieldId",
  "fields",
  "cardinality",
  "updateConstraint",
  "deleteConstraint",
];

function isEqual(a, b) {
  if (a === b) return true;

  if (Array.isArray(a) && Array.isArray(b)) {
    return a.length === b.length && a.every((item, i) => isEqual(item, b[i]));
  }

  if (a && b && typeof a === "object" && typeof b === "object") {
    const keys = Object.keys(a);
    return (
      keys.length === Object.keys(b).length &&
      keys.every((key) => isEqual(a[key], b[key]))
    );
  }

  return false;
}

function changedValues(before, after, keys) {
  const values = {};
  for (const key of keys) {
    if (!isEqual(before[key], after[key])) values[key] = after[key];
  }
  return values;
}

function byId(items) {
  return new Map(items.map((item) => [item.id, item]));
}

function diffFields(before, after) {
  const beforeFields = before.fields ?? [];
  const afterFields = after.fields ?? [];

  const sameShape =
    beforeFields.length === afterFields.length &&
    beforeFields.every((field, i) => field.id === afterFields[i].id);
  if (!sameShape) return { replaceFields: true, updates: [] };

  const updates = [];
  afterFields.forEach((field, i) => {
    const values = changedValues(beforeFields[i], field, FIELD_KEYS);
    if (Object.keys(values).length) {
      updates.push({
        target: "field",
        action: "update",
        tableId: after.id,
        fieldId: field.id,
        values,
      });
    }
  });

  return { replaceFields: false, updates };
}

function diffTables(before, after) {
  const beforeById = byId(before);
  const afterById = byId(after);

  const deletes = before
    .filter((table) => !afterById.has(table.id))
    .map((table) => ({ target: "table", action: "delete", id: table.id }));

  const creates = after
    .filter((table) => !beforeById.has(table.id))
    .map((table) => ({ target: "table", action: "create", table }));

  const updates = [];
  const fieldUpdates = [];

  for (const table of after) {
    const previous = beforeById.get(table.id);
    if (!previous) continue;

    const values = changedValues(previous, table, TABLE_KEYS);
    const fields = diffFields(previous, table);
    if (fields.replaceFields) values.fields = table.fields;
    else fieldUpdates.push(...fields.updates);

    if (Object.keys(values).length) {
      updates.push({ target: "table", action: "update", id: table.id, values });
    }
  }

  return { deletes, creates, updates, fieldUpdates };
}

function diffRelationships(before, after) {
  const beforeById = byId(before);
  const afterById = byId(after);

  const deletes = before
    .filter((rel) => !afterById.has(rel.id))
    .map((rel) => ({ target: "relationship", action: "delete", id: rel.id }));

  const creates = after
    .filter((rel) => !beforeById.has(rel.id))
    .map((rel) => ({
      target: "relationship",
      action: "create",
      relationship: rel,
    }));

  const updates = [];
  for (const rel of after) {
    const previous = beforeById.get(rel.id);
    if (!previous) continue;

    const values = changedValues(previous, rel, RELATIONSHIP_KEYS);
    if (Object.keys(values).length) {
      updates.push({
        target: "relationship",
        action: "update",
        id: rel.id,
        values,
      });
    }
  }

  return { deletes, creates, updates };
}

export function diffDiagram(from, to) {
  const enums = isEqual(from.enums ?? [], to.enums ?? [])
    ? []
    : [{ target: "enums", action: "update", enums: to.enums ?? [] }];

  const tables = diffTables(from.tables ?? [], to.tables ?? []);
  const relationships = diffRelationships(
    from.relationships ?? [],
    to.relationships ?? [],
  );

  return [
    ...enums,
    ...tables.deletes,
    ...tables.creates,
    ...tables.updates,
    ...tables.fieldUpdates,
    ...relationships.deletes,
    ...relationships.creates,
    ...relationships.updates,
  ];
}

