import { dbToTypes } from "../../data/datatypes";
import { buildViewSQL, resolveViewColumns } from "../views";
import { jsonToMermaid } from "./mermaid";
import { databases } from "../../data/databases";
import { getRelationshipFields } from "../utils";

function formatMarkdownTable(headers, rows) {
  const allRows = [headers, ...rows];
  const colWidths = headers.map((_, colIndex) =>
    Math.max(...allRows.map((row) => (row[colIndex] ?? "").length)),
  );

  const pad = (cell, width) => (cell ?? "").padEnd(width);
  const separator = colWidths.map((w) => "-".repeat(w)).join(" | ");
  const headerRow = headers.map((h, i) => pad(h, colWidths[i])).join(" | ");
  const dataRows = rows
    .map((row) => `| ${row.map((cell, i) => pad(cell, colWidths[i])).join(" | ")} |`)
    .join("\n");

  return `| ${headerRow} |\n| ${separator} |\n${dataRows}`;
}

export function jsonToDocumentation(obj) {
  const documentationSummary = obj.tables
    .map((table) => {
      return `\t- [${table.name}](#${table.name.toLowerCase()})`;
    })
    .join("\n");

  const documentationEntities = obj.tables
    .map((table) => {
      let enums = "";

      const fieldRows = table.fields.map((field) => {
        const fieldType =
          field.type +
          ((dbToTypes[obj.database][field.type].isSized ||
            dbToTypes[obj.database][field.type].hasPrecision) &&
          field.size &&
          field.size !== ""
            ? "(" + field.size + ")"
            : "");

        enums +=
          field.type === "ENUM" && field.values && field.values.length > 0
            ? `##### ${field.name}\n\n${field.values.map((v) => `- ${v}`).join("\n")}\n`
            : "";

        const settings =
          `${field.primary ? "🔑 PK, " : ""}` +
          `${field.notNull ? "not null" : "null"}` +
          `${field.unique ? ", unique" : ""}` +
          `${field.increment ? ", autoincrement" : ""}` +
          `${field.default ? `, default: ${field.default}` : ""}`;

        const references = relationshipByField(
          table.id,
          obj.relationships,
          field.id,
        ).join(", ");

        return [`**${field.name}**`, fieldType, settings, references, field.comment ?? ""];
      });

      const fieldsTable = formatMarkdownTable(
        ["Name", "Type", "Settings", "References", "Note"],
        fieldRows,
      );

      let indexesSection = "";
      if (table.indices.length > 0) {
        const indexRows = table.indices.map((index) => [
          index.name,
          index.unique ? "✅" : "",
          index.fields.join(", "),
        ]);
        indexesSection =
          "\n#### Indexes\n" +
          formatMarkdownTable(["Name", "Unique", "Columns"], indexRows);
      }

      let uniqueConstraintsSection = "";
      if ((table.uniqueConstraints || []).length > 0) {
        const ucRows = table.uniqueConstraints.map((uc) => [
          uc.name,
          uc.fields.join(", "),
        ]);
        uniqueConstraintsSection =
          "\n#### Unique constraints\n" +
          formatMarkdownTable(["Name", "Columns"], ucRows);
      }

      return (
        `### ${table.name}\n${table.comment ? table.comment : ""}\n` +
        `${fieldsTable} \n${enums.length > 0 ? "\n#### Enums\n" + enums : ""}\n` +
        indexesSection +
        uniqueConstraintsSection
      );
    })
    .join("\n");

  function relationshipByField(table, relationships, fieldId) {
    return relationships
      .filter(
        (r) =>
          r.startTableId === table &&
          getRelationshipFields(r).some((p) => p.startFieldId === fieldId),
      )
      .map((rel) => rel.name);
  }

  const documentationRelationships = obj.relationships?.length
    ? obj.relationships
        .map((r) => {
          const startTable = obj.tables.find(
            (t) => t.id === r.startTableId,
          ).name;
          const endTable = obj.tables.find((t) => t.id === r.endTableId).name;
          return `- **${startTable} to ${endTable}**: ${r.cardinality}\n`;
        })
        .join("")
    : "";

  const documentationTypes =
    databases[obj.database].hasTypes && obj.types.length > 0
      ? obj.types
          .map((type) => {
            const rows = [[type.name, type.fields.map((f) => f.name).join(", "), type.comment ?? ""]];
            return formatMarkdownTable(["Name", "Columns", "Note"], rows);
          })
          .join("\n")
      : "";

  const views = obj.views ?? [];
  const documentationViews = views.length
    ? views
        .map((view) => {
          const columns = resolveViewColumns(view, obj.tables);
          const columnsTable = columns.length
            ? formatMarkdownTable(
                ["Name", "Type", "Source"],
                columns.map((c) => [c.name, c.type ?? "", c.source ?? ""]),
              )
            : "";
          const sql = buildViewSQL(view, obj.tables, obj.database);
          return (
            `### ${view.name}${view.materialized ? " (materialized)" : ""}\n\n` +
            `${view.comment ? `${view.comment}\n\n` : ""}` +
            `${columnsTable}${columnsTable ? "\n" : ""}` +
            `${sql ? `\`\`\`sql\n${sql}\n\`\`\`\n` : ""}`
          );
        })
        .join("\n")
    : "";

  return (
    `# ${obj.title} documentation\n## Summary\n\n- [Introduction](#introduction)\n- [Database Type](#database-type)\n` +
    `- [Table Structure](#table-structure)\n${documentationSummary}\n- [Relationships](#relationships)\n${views.length > 0 ? `- [Views](#views)\n` : ""}- [Database Diagram](#database-diagram)\n\n` +
    `## Introduction\n\n## Database type\n\n- **Database system:** ` +
    `${databases[obj.database].name}\n## Table structure\n\n${documentationEntities}` +
    `\n## Relationships\n\n${documentationRelationships}\n` +
    `${databases[obj.database].hasTypes && obj.types.length > 0 ? `## Types\n\n` + documentationTypes + `\n\n` : ""}` +
    `${views.length > 0 ? `## Views\n\n` + documentationViews + `\n` : ""}` +
    `## Database Diagram\n\n\`\`\`mermaid\n${jsonToMermaid(obj)}\n\`\`\``
  );
}

src/utils/exportAs/mermaid.js:
import { Cardinality } from "../../data/constants";
import { dbToTypes } from "../../data/datatypes";
import i18n from "../../i18n/i18n";

export function jsonToMermaid(obj) {
  function getMermaidRelationship(relationship) {
    switch (relationship) {
      case i18n.t(Cardinality.ONE_TO_ONE):
      case Cardinality.ONE_TO_ONE:
        return "||--||";
      case i18n.t(Cardinality.MANY_TO_ONE):
      case Cardinality.MANY_TO_ONE:
        return "}o--||";
      case i18n.t(Cardinality.ONE_TO_MANY):
      case Cardinality.ONE_TO_MANY:
        return "||--o{";
      default:
        return "--";
    }
  }

  const mermaidEntities = obj.tables
    .map((table) => {
      const fields = table.fields
        .map((field) => {
          const fieldType =
            field.type +
            ((dbToTypes[obj.database][field.type].isSized ||
              dbToTypes[obj.database][field.type].hasPrecision) &&
            field.size &&
            field.size !== ""
              ? "(" + field.size + ")"
              : "");
          return `\t\t${fieldType} ${field.name}`;
        })
        .join("\n");
      return `\t${table.name} {\n${fields}\n\t}`;
    })
    .join("\n\n");

  const mermaidRelationships = obj.relationships?.length
    ? obj.relationships
        .map((r) => {
          const startTable = obj.tables.find(
            (t) => t.id === r.startTableId,
          ).name;
          const endTable = obj.tables.find((t) => t.id === r.endTableId).name;
          return `\t${startTable} ${getMermaidRelationship(r.cardinality)} ${endTable} : references`;
        })
        .join("\n")
    : "";

  return `erDiagram\n${mermaidRelationships ? `${mermaidRelationships}\n\n` : ""}${mermaidEntities}`;
}

src/utils/exportSQL/generic.js:
import { DB } from "../../data/constants";
import { appendViews } from "../views";
import { dbToTypes, defaultTypes } from "../../data/datatypes";
import {
  escapeQuotes,
  getInlineFK,
  parseDefault,
  uniqueConstraintClause,
  getFkColumnNames,
} from "./shared";

export function getJsonType(f) {
  if (!Object.keys(defaultTypes).includes(f.type)) {
    return '{ "type" : "object", additionalProperties : true }';
  }
  switch (f.type) {
    case "INT":
    case "SMALLINT":
    case "BIGINT":
    case "DECIMAL":
    case "NUMERIC":
    case "REAL":
    case "FLOAT":
      return '{ "type" : "number" }';
    case "BOOLEAN":
      return '{ "type" : "boolean" }';
    case "JSON":
      return '{ "type" : "object", "additionalProperties" : true }';
    case "ENUM":
      return `{\n\t\t\t\t\t"type" : "string",\n\t\t\t\t\t"enum" : [${f.values
        .map((v) => `"${v}"`)
        .join(", ")}]\n\t\t\t\t}`;
    case "SET":
      return `{\n\t\t\t\t\t"type": "array",\n\t\t\t\t\t"items": {\n\t\t\t\t\t\t"type": "string",\n\t\t\t\t\t\t"enum": [${f.values
        .map((v) => `"${v}"`)
        .join(", ")}]\n\t\t\t\t\t}\n\t\t\t\t}`;
    default:
      return '{ "type" : "string"}';
  }
}

export function generateSchema(type) {
  return `{\n\t\t\t"$schema": "http://json-schema.org/draft-04/schema#",\n\t\t\t"type": "object",\n\t\t\t"properties": {\n\t\t\t\t${type.fields
    .map((f) => `"${f.name}" : ${getJsonType(f)}`)
    .join(
      ",\n\t\t\t\t",
    )}\n\t\t\t},\n\t\t\t"additionalProperties": false\n\t\t}`;
}

export function getTypeString(
  field,
  currentDb,
  dbms = DB.MYSQL,
  baseType = false,
) {
  if (dbms === DB.MYSQL) {
    if (field.type === "UUID") {
      return `VARCHAR(36)`;
    }
    if (
      dbToTypes[currentDb][field.type].isSized ||
      dbToTypes[currentDb][field.type].hasPrecision
    ) {
      return `${field.type}${field.size ? `(${field.size})` : ""}`;
    }
    if (field.type === "SET" || field.type === "ENUM") {
      return `${field.type}(${field.values.map((v) => `"${v}"`).join(", ")})`;
    }
    if (!Object.keys(defaultTypes).includes(field.type)) {
      return "JSON";
    }
    return field.type;
  } else if (dbms === DB.POSTGRES) {
    if (field.type === "SMALLINT" && field.increment) {
      return "smallserial";
    }
    if (field.type === "INT" && field.increment) {
      return "serial";
    }
    if (field.type === "BIGINT" && field.increment) {
      return "bigserial";
    }
    if (field.type === "ENUM") {
      return `${field.name}_t`;
    }
    if (field.type === "SET") {
      return `${field.name}_t[]`;
    }
    if (field.type === "TIMESTAMP") {
      return "TIMESTAMPTZ";
    }
    if (field.type === "DATETIME") {
      return `timestamp`;
    }
    if (dbToTypes[currentDb][field.type].isSized && field.size) {
      const type =
        field.type === "BINARY"
          ? "bit"
          : field.type === "VARBINARY"
            ? "bit varying"
            : field.type.toLowerCase();
      return `${type}(${field.size})`;
    }
    if (
      dbToTypes[currentDb][field.type].hasPrecision &&
      field.size &&
      field.size.trim() !== ""
    ) {
      return `${field.type.toLowerCase()}${field.size ? `(${field.size})` : ""}`;
    }
    return field.type.toLowerCase();
  } else if (dbms === DB.MSSQL) {
    let type = field.type;
    switch (field.type) {
      case "ENUM":
        return baseType
          ? "NVARCHAR(255)"
          : `NVARCHAR(255) CHECK([${field.name}] in (${field.values
              .map((v) => `'${v}'`)
              .join(", ")}))`;
      case "VARCHAR":
        type = `NVARCHAR`;
        break;
      case "UUID":
        type = "UNIQUEIDENTIFIER";
        break;
      case "DOUBLE":
        type = "FLOAT";
        break;
      case "BOOLEAN":
        return "BIT";
      case "SET":
        return "NVARCHAR(255)";
      case "BLOB":
        return "VARBINARY(MAX)";
      case "JSON":
        return "NVARCHAR(MAX)";
      case "TEXT":
        return "TEXT";
      default:
        type = field.type;
        break;
    }
    if (dbToTypes[currentDb][field.type].isSized) {
      return `${type}(${field.size})`;
    }

    return type;
  } else if (dbms === DB.ORACLESQL) {
    let oracleType;
    switch (field.type) {
      case "BIGINT":
        oracleType = "NUMBER";
        break;
      case "VARCHAR":
        oracleType = "VARCHAR2";
        break;
      case "TEXT":
        oracleType = "CLOB";
        break;
      case "TIME":
      case "DATETIME":
        oracleType = "TIMESTAMP";
        break;
      case "BINARY":
      case "VARBINARY":
        oracleType = "RAW";
        break;
      case "UUID":
        oracleType = "RAW(16)";
        break;
      case "SET":
      case "ENUM":
        oracleType = field.name + "_t";
        break;
      default:
        oracleType = field.type;
        break;
    }
    const typeInfo = dbToTypes[currentDb][oracleType];
    if (typeInfo.isSized || typeInfo.hasPrecision) {
      if (oracleType === "NUMBER") {
        return `${oracleType}${field.size ? `(${field.size})` : "(38,0)"}`;
      } else {
        return `${oracleType}${field.size ? `(${field.size})` : ""}`;
      }
    }

    return oracleType;
  }
}

function tablesToMySQL(obj) {
  return `${obj.tables
    .map(
      (table) =>
        `CREATE TABLE IF NOT EXISTS \`${table.name}\` (\n${table.fields
          .map(
            (field) =>
              `\t\`${
                field.name
              }\` ${getTypeString(field, obj.database)}${field.notNull ? " NOT NULL" : ""}${
                field.increment ? " AUTO_INCREMENT" : ""
              }${field.unique ? " UNIQUE" : ""}${
                field.default !== ""
                  ? ` DEFAULT ${parseDefault(field, obj.database)}`
                  : ""
              }${
                field.check === "" ||
                !dbToTypes[obj.database][field.type].hasCheck
                  ? !Object.keys(defaultTypes).includes(field.type)
                    ? ` CHECK(\n\t\tJSON_SCHEMA_VALID("${generateSchema(
                        obj.types.find(
                          (t) => t.name === field.type.toLowerCase(),
                        ),
                      )}", \`${field.name}\`))`
                    : ""
                  : ` CHECK(${field.check})`
              }${field.comment ? ` COMMENT '${escapeQuotes(field.comment)}'` : ""}`,
          )
          .join(",\n")}${
          table.fields.filter((f) => f.primary).length > 0
            ? `,\n\tPRIMARY KEY(${table.fields
                .filter((f) => f.primary)
                .map((f) => `\`${f.name}\``)
                .join(", ")})`
            : ""
        }${uniqueConstraintClause(table, (s) => `\`${s}\``)}\n)${table.comment ? ` COMMENT='${escapeQuotes(table.comment)}'` : ""};\n${`\n${table.indices
          .map(
            (i) =>
              `CREATE ${i.unique ? "UNIQUE " : ""}INDEX \`${i.name}\`\nON \`${table.name}\` (${i.fields
                .map((f) => `\`${f}\``)
                .join(", ")});`,
          )
          .join("\n")}`}`,
    )
    .join("\n")}\n${obj.references
    .map((r) => {
      const { name: startName, fields: startFields } = obj.tables.find(
        (t) => t.id === r.startTableId,
      );

      const endTable = obj.tables.find((t) => t.id === r.endTableId);
      const { name: endName } = endTable;
      const { startColumns, endColumns } = getFkColumnNames(
        r,
        { fields: startFields },
        endTable,
      );
      return `ALTER TABLE \`${startName}\`\nADD FOREIGN KEY(${startColumns
        .map((c) => `\`${c}\``)
        .join(", ")}) REFERENCES \`${endName}\`(${endColumns
        .map((c) => `\`${c}\``)
        .join(", ")})\nON UPDATE ${r.updateConstraint.toUpperCase()} ON DELETE ${r.deleteConstraint.toUpperCase()};`;
    })
    .join("\n")}`;
}

function tablesToPostgreSQL(obj) {
  const typeStatements = obj.types
    .map((type) => {
      const enumStatements = type.fields
        .filter((f) => f.type === "ENUM" || f.type === "SET")
        .map(
          (f) =>
            `CREATE TYPE "${f.name}_t" AS ENUM (${f.values
              .map((v) => `'${v}'`)
              .join(", ")});`,
        )
        .join("\n");
      const compositeStatement = `CREATE TYPE ${type.name} AS (\n${type.fields
        .map(
          (f) => `\t${f.name} ${getTypeString(f, obj.database, DB.POSTGRES)}`,
        )
        .join(",\n")}\n);`;
      if (enumStatements) {
        return `${enumStatements}\n${
          type.comment === "" ? "" : `/**\n${type.comment}\n*/\n`
        }${compositeStatement}`;
      }
      return `${compositeStatement}${
        type.comment && type.comment.trim() != ""
          ? `\n\nCOMMENT ON TYPE ${type.name} IS '${escapeQuotes(type.comment)}';`
          : ""
      }`;
    })
    .join("\n\n");

  const tableStatements = obj.tables
    .map((table) => {
      const fieldEnumStatements = table.fields
        .filter((f) => f.type === "ENUM" || f.type === "SET")
        .map(
          (f) =>
            `CREATE TYPE "${f.name}_t" AS ENUM (${f.values
              .map((v) => `'${v}'`)
              .join(", ")});`,
        )
        .join("\n");
      const createStatement = `CREATE TABLE IF NOT EXISTS "${table.name}" (\n${table.fields
        .map(
          (field) =>
            `${field.comment === "" ? "" : `\t-- ${field.comment}\n`}\t"${
              field.name
            }" ${getTypeString(field, obj.database, DB.POSTGRES)}${
              field.notNull ? " NOT NULL" : ""
            }${field.unique ? " UNIQUE" : ""}${
              field.default !== "" ? ` DEFAULT ${parseDefault(field)}` : ""
            }${
              field.check === "" ||
              !dbToTypes[obj.database][field.type].hasCheck
                ? ""
                : ` CHECK(${field.check})`
            }`,
        )
        .join(",\n")}${
        table.fields.filter((f) => f.primary).length > 0
          ? `,\n\tPRIMARY KEY(${table.fields
              .filter((f) => f.primary)
              .map((f) => `"${f.name}"`)
              .join(", ")})`
          : ""
      }${uniqueConstraintClause(table, (s) => `"${s}"`)}\n);`;
      const commentStatements = [
        table.comment != ""
          ? `COMMENT ON TABLE ${table.name} IS '${escapeQuotes(table.comment)}';`
          : "",
        ...table.fields.map((field) =>
          field.comment.trim() !== ""
            ? `COMMENT ON COLUMN ${table.name}.${field.name} IS '${escapeQuotes(field.comment)}';`
            : "",
        ),
      ]
        .filter(Boolean)
        .join("\n");
      const indexStatements = table.indices
        .map(
          (i) =>
            `CREATE ${i.unique ? "UNIQUE " : ""}INDEX "${
              i.name
            }"\nON "${table.name}" (${i.fields
              .map((f) => `"${f}"`)
              .join(", ")});`,
        )
        .join("\n");
      return [
        fieldEnumStatements,
        createStatement,
        commentStatements,
        indexStatements,
      ]
        .filter(Boolean)
        .join("\n\n");
    })
    .join("\n\n");

  const foreignKeyStatements = obj.references
    .map((r) => {
      const { name: startName, fields: startFields } = obj.tables.find(
        (t) => t.id === r.startTableId,
      );

      const endTable = obj.tables.find((t) => t.id === r.endTableId);
      const { name: endName } = endTable;
      const { startColumns, endColumns } = getFkColumnNames(
        r,
        { fields: startFields },
        endTable,
      );
      return `ALTER TABLE "${startName}"\nADD FOREIGN KEY(${startColumns
        .map((c) => `"${c}"`)
        .join(", ")}) REFERENCES "${endName}"(${endColumns
        .map((c) => `"${c}"`)
        .join(", ")})\nON UPDATE ${r.updateConstraint.toUpperCase()} ON DELETE ${r.deleteConstraint.toUpperCase()};`;
    })
    .join("\n");

  return [typeStatements, tableStatements, foreignKeyStatements]
    .filter(Boolean)
    .join("\n\n");
}

export function getSQLiteType(field) {
  switch (field.type) {
    case "INT":
    case "SMALLINT":
    case "BIGINT":
    case "BOOLEAN":
      return "INTEGER";
    case "DECIMAL":
    case "NUMERIC":
    case "FLOAT":
    case "DOUBLE":
    case "REAL":
      return "REAL";
    case "CHAR":
    case "VARCHAR":
    case "UUID":
    case "TEXT":
    case "DATE":
    case "TIME":
    case "TIMESTAMP":
    case "DATETIME":
    case "BINARY":
    case "VARBINARY":
      return "TEXT";
    case "ENUM":
      return `TEXT CHECK("${field.name}" in (${field.values
        .map((v) => `'${v}'`)
        .join(", ")}))`;
    default:
      return "BLOB";
  }
}

function tablesToSQLite(obj) {
  return obj.tables
    .map((table) => {
      const inlineFK = getInlineFK(table, obj);
      return `${
        table.comment === "" ? "" : `/* ${table.comment} */\n`
      }CREATE TABLE IF NOT EXISTS "${table.name}" (\n${table.fields
        .map(
          (field) =>
            `${field.comment === "" ? "" : `\t-- ${field.comment}\n`}\t"${
              field.name
            }" ${getSQLiteType(field)}${field.notNull ? " NOT NULL" : ""}${
              field.unique ? " UNIQUE" : ""
            }${field.default !== "" ? ` DEFAULT ${parseDefault(field, obj.database)}` : ""}${
              field.check === "" ||
              !dbToTypes[obj.database][field.type].hasCheck
                ? ""
                : ` CHECK(${field.check})`
            }`,
        )
        .join(",\n")}${
        table.fields.filter((f) => f.primary).length > 0
          ? `,\n\tPRIMARY KEY(${table.fields
              .filter((f) => f.primary)
              .map((f) => `"${f.name}"`)
              .join(", ")})`
          : ""
      }${inlineFK !== "" ? ",\n" : ""}${inlineFK}${uniqueConstraintClause(table, (s) => `"${s}"`)}\n);\n${table.indices
        .map(
          (i) =>
            `\nCREATE ${i.unique ? "UNIQUE " : ""}INDEX IF NOT EXISTS "${
              i.name
            }"\nON "${table.name}" (${i.fields
              .map((f) => `"${f}"`)
              .join(", ")});`,
        )
        .join("\n")}`;
    })
    .join("\n");
}

function tablesToMariaDB(obj) {
  return `${obj.tables
    .map(
      (table) =>
        `CREATE OR REPLACE TABLE \`${table.name}\` (\n${table.fields
          .map(
            (field) =>
              `\t\`${
                field.name
              }\` ${getTypeString(field, obj.database, DB.MYSQL)}${field.notNull ? " NOT NULL" : ""}${
                field.increment ? " AUTO_INCREMENT" : ""
              }${field.unique ? " UNIQUE" : ""}${
                field.default !== ""
                  ? ` DEFAULT ${parseDefault(field, obj.database)}`
                  : ""
              }${
                field.check === "" ||
                !dbToTypes[obj.database][field.type].hasCheck
                  ? !Object.keys(defaultTypes).includes(field.type)
                    ? ` CHECK(\n\t\tJSON_SCHEMA_VALID('${generateSchema(
                        obj.types.find(
                          (t) => t.name === field.type.toLowerCase(),
                        ),
                      )}', \`${field.name}\`))`
                    : ""
                  : ` CHECK(${field.check})`
              }${field.comment ? ` COMMENT '${escapeQuotes(field.comment)}'` : ""}`,
          )
          .join(",\n")}${
          table.fields.filter((f) => f.primary).length > 0
            ? `,\n\tPRIMARY KEY(${table.fields
                .filter((f) => f.primary)
                .map((f) => `\`${f.name}\``)
                .join(", ")})`
            : ""
        }${uniqueConstraintClause(table, (s) => `\`${s}\``)}\n)${table.comment ? ` COMMENT='${escapeQuotes(table.comment)}'` : ""};${`\n${table.indices
          .map(
            (i) =>
              `CREATE ${i.unique ? "UNIQUE " : ""}INDEX \`${
                i.name
              }\`\nON \`${table.name}\` (${i.fields
                .map((f) => `\`${f}\``)
                .join(", ")});`,
          )
          .join("\n")}`}`,
    )
    .join("\n")}\n${obj.references
    .map((r) => {
      const { name: startName, fields: startFields } = obj.tables.find(
        (t) => t.id === r.startTableId,
      );

      const endTable = obj.tables.find((t) => t.id === r.endTableId);
      const { name: endName } = endTable;
      const { startColumns, endColumns } = getFkColumnNames(
        r,
        { fields: startFields },
        endTable,
      );
      return `ALTER TABLE \`${startName}\`\nADD FOREIGN KEY(${startColumns
        .map((c) => `\`${c}\``)
        .join(", ")}) REFERENCES \`${endName}\`(${endColumns
        .map((c) => `\`${c}\``)
        .join(", ")})\nON UPDATE ${r.updateConstraint.toUpperCase()} ON DELETE ${r.deleteConstraint.toUpperCase()};`;
    })
    .join("\n")}`;
}

function tablesToSQLServer(obj) {
  return `${obj.types
    .filter((type) => type.fields.length > 0)
    .map((type) => {
      return `${
        type.comment === "" ? "" : `/**\n${type.comment}\n*/\n`
      }CREATE TYPE [${type.name}] FROM ${getTypeString(
        type.fields[0],
        obj.database,
        DB.MSSQL,
        true,
      )};\nGO\n`;
    })
    .join("\n")}\n${obj.tables
    .map(
      (table) =>
        `${
          table.comment === "" ? "" : `/**\n${table.comment}\n*/\n`
        }CREATE TABLE [${table.name}] (\n${table.fields
          .map(
            (field) =>
              `${field.comment === "" ? "" : `\t-- ${field.comment}\n`}\t[${
                field.name
              }] ${getTypeString(field, obj.database, DB.MSSQL)}${
                field.notNull ? " NOT NULL" : ""
              }${field.increment ? " IDENTITY" : ""}${
                field.unique ? " UNIQUE" : ""
              }${
                field.default !== ""
                  ? ` DEFAULT ${parseDefault(field, obj.database)}`
                  : ""
              }${
                field.check === "" ||
                !dbToTypes[obj.database][field.type].hasCheck
                  ? ""
                  : ` CHECK(${field.check})`
              }`,
          )
          .join(",\n")}${
          table.fields.filter((f) => f.primary).length > 0
            ? `,\n\tPRIMARY KEY(${table.fields
                .filter((f) => f.primary)
                .map((f) => `[${f.name}]`)
                .join(", ")})`
            : ""
        }${uniqueConstraintClause(table, (s) => `[${s}]`)}\n);\nGO\n${table.indices
          .map(
            (i) =>
              `\nCREATE ${i.unique ? "UNIQUE " : ""}INDEX [${
                i.name
              }]\nON [${table.name}] (${i.fields
                .map((f) => `[${f}]`)
                .join(", ")});\nGO\n`,
          )
          .join("")}`,
    )
    .join("\n")}\n${obj.references
    .map((r) => {
      const { name: startName, fields: startFields } = obj.tables.find(
        (t) => t.id === r.startTableId,
      );

      const endTable = obj.tables.find((t) => t.id === r.endTableId);
      const { name: endName } = endTable;
      const { startColumns, endColumns } = getFkColumnNames(
        r,
        { fields: startFields },
        endTable,
      );
      return `ALTER TABLE [${startName}]\nADD FOREIGN KEY(${startColumns
        .map((c) => `[${c}]`)
        .join(", ")}) REFERENCES [${endName}](${endColumns
        .map((c) => `[${c}]`)
        .join(", ")})\nON UPDATE ${r.updateConstraint.toUpperCase()} ON DELETE ${r.deleteConstraint.toUpperCase()};\nGO`;
    })
    .join("\n")}`;
}

function tablesToOracleSQL(obj) {
  return `${obj.tables
    .map(
      (table) =>
        `${
          table.fields.filter((f) => f.type === "ENUM" || f.type === "SET")
            .length > 0
            ? `${table.fields
                .filter((f) => f.type === "ENUM" || f.type === "SET")
                .map(
                  (f) =>
                    `CREATE DOMAIN "${f.name}_t" AS ENUM (${f.values
                      .map((v) => `'${v}'`)
                      .join(", ")});\n`,
                )
                .join("\n")}\n`
            : ""
        }${
          table.comment === "" ? "" : `/* ${table.comment} */\n`
        }CREATE TABLE "${table.name}" (\n${table.fields
          .map(
            (field) =>
              `${field.comment === "" ? "" : `  -- ${field.comment}\n`}  "${
                field.name
              }" ${getTypeString(field, obj.database, DB.ORACLESQL)}${
                field.notNull ? " NOT NULL" : ""
              }${field.increment ? " GENERATED ALWAYS AS IDENTITY" : ""}${
                field.unique ? " UNIQUE" : ""
              }${
                field.default !== ""
                  ? ` DEFAULT ${parseDefault(field, obj.database)}`
                  : ""
              }${
                field.check === "" ||
                !dbToTypes[obj.database][field.type].hasCheck
                  ? ""
                  : ` CHECK (${field.check})`
              }`,
          )
          .join(",\n")}${
          table.fields.filter((f) => f.primary).length > 0
            ? `,\n  PRIMARY KEY (${table.fields
                .filter((f) => f.primary)
                .map((f) => `"${f.name}"`)
                .join(", ")})`
            : ""
        }${uniqueConstraintClause(table, (s) => `"${s}"`)}\n);\n${table.indices
          .map(
            (i) =>
              `\nCREATE ${i.unique ? "UNIQUE " : ""}INDEX "${i.name}"\n  ON "${
                table.name
              }" (${i.fields.map((f) => `"${f}"`).join(", ")});`,
          )
          .join("\n")}`,
    )
    .join("\n\n")}\n${obj.references
    .map((r) => {
      const { name: startName, fields: startFields } = obj.tables.find(
        (t) => t.id === r.startTableId,
      );

      const endTable = obj.tables.find((t) => t.id === r.endTableId);
      const { name: endName } = endTable;
      const { startColumns, endColumns } = getFkColumnNames(
        r,
        { fields: startFields },
        endTable,
      );
      return `ALTER TABLE "${startName}"\nADD CONSTRAINT "${r.name}" FOREIGN KEY (${startColumns
        .map((c) => `"${c}"`)
        .join(", ")}) REFERENCES "${endName}"(${endColumns
        .map((c) => `"${c}"`)
        .join(", ")});`;
    })
    .join("\n")}`;
}

export function jsonToMySQL(obj) {
  return appendViews(tablesToMySQL(obj), obj, DB.MYSQL);
}

export function jsonToPostgreSQL(obj) {
  return appendViews(tablesToPostgreSQL(obj), obj, DB.POSTGRES);
}

export function jsonToSQLite(obj) {
  return appendViews(tablesToSQLite(obj), obj, DB.SQLITE);
}

export function jsonToMariaDB(obj) {
  return appendViews(tablesToMariaDB(obj), obj, DB.MARIADB);
}

export function jsonToSQLServer(obj) {
  return appendViews(tablesToSQLServer(obj), obj, DB.MSSQL);
}

export function jsonToOracleSQL(obj) {
  return appendViews(tablesToOracleSQL(obj), obj, DB.ORACLESQL);
}

