                (f) => f.name === startFieldNames[i],
              );
              const ef = endTable.fields.find(
                (f) => f.name === endFieldNames[i],
              );
              if (!sf || !ef) break;
              fieldPairs.push({ startFieldId: sf.id, endFieldId: ef.id });
